t32().ToString("x8"):null,raw_cli_token_not_used_as_native=true,initial_generic_calling_convention_bit_only_normalized=normalizedOldGenericConvention,raw_calling_convention=(int)m.CallingConvention,initial_calling_convention=matches.Length==1?(int?)matches[0].CallingConvention:null,initial_same_name_candidates=witness==null&&ot!=null?ot.Methods.Where(x=>x.Name==m.Name&&x.GenericParameters.Count==m.GenericParameters.Count&&x.Parameters.Count==m.Parameters.Count&&x.HasThis==m.HasThis).Select(x=>new{original_token=Token(x),canonical_signature=CanonicalMetadataSignatures.Method(x),flags=(uint)x.Attributes,impl_flags=(uint)x.ImplAttributes}).ToArray():null,return_shape=returns,parameters_shape=parameters,generic_arity=m.GenericParameters.Count,has_this=m.HasThis,flags=(uint)m.Attributes,impl_flags=(uint)m.ImplAttributes,initial_provider_flags=matches.Length==1?(uint?)matches[0].Attributes:null,initial_provider_impl_flags=matches.Length==1?(uint?)matches[0].ImplAttributes:null,error}));count++;}}
  using var summary=File.Create(args[3]);JsonSerializer.Serialize(summary,new{schema="core-raw-method-flags-initial-token-witness/v1",method_count=count,unsupported_or_unwitnessed_methods=bad,excluded_recovery_helper_methods=helpers,helper_exclusions=excluded,project_modified=false,game_code_executed=false},new JsonSerializerOptions{WriteIndented=true});return 0;}
